<div class="form-grid"><label>ชื่อ Badge<input name="name" value="{{$badge?->name}}" required></label><label>ไอคอน<input name="icon" value="{{$badge?->icon??'🏅'}}" required></label><label>เงื่อนไข<select name="criteria_type"><option value="trees" {{$badge?->criteria_type==='trees'?'selected':''}}>จำนวนต้นไม้</option><option value="activities" {{$badge?->criteria_type==='activities'?'selected':''}}>จำนวนกิจกรรม</option><option value="points" {{$badge?->criteria_type==='points'?'selected':''}}>คะแนนสะสม</option></select></label><label>จำนวนที่ต้องทำ<input type="number" name="criteria_value" min="1" value="{{$badge?->criteria_value??1}}" required></label><label>คะแนนโบนัส<input type="number" name="bonus_points" min="0" value="{{$badge?->bonus_points??0}}" required></label></div><label>รายละเอียด<textarea name="description" required>{{$badge?->description}}</textarea></label>
